       integer(c_int), value :: nnz
       type(c_ptr), value :: descr
       real(c_float) :: coo_val(*)
       integer(c_int) :: coo_row_ind(*)
       integer(c_int) :: coo_col_ind(*)
       real(c_float) :: A(*)
       integer(c_int), value :: ld
       integer(c_int) :: scoo2dense
    end function rocsparse_scoo2dense

