    function rocsparse_dcsr2gebsr(handle, dir, m, n, csr_descr, csr_val, csr_row_ptr, csr_col_ind, &
                                  bsr_descr, bsr_val, bsr_row_ptr, bsr_col_ind, row_block_dim, &
