    !> nnz_C,
    !> csr_row_ptr_C,
    !> csr_col_ind_C,
    !> info_C,
    !> buffer);
    !> hipMalloc((void**)&csr_val_C, sizeof(float) * nnz_C);
    !>
    !> rocsparse_scsrgemm_numeric(handle,
    !> rocsparse_operation_none,
    !> rocsparse_operation_none,
    !> m,
    !> n,
    !> k,
    !> &alpha,
    !> descr_A,
    !> nnz_A,
    !> csr_val_A,
    !> csr_row_ptr_A,
    !> csr_col_ind_A,
    !> descr_B,
