       type(c_ptr), value :: handle
       type(c_ptr), value :: x
       type(c_ptr), value :: y
       integer(c_int) :: scatter
    end function rocsparse_scatter

    !---------------------------------------------
    ! rocsparse_sddmm_buffer_size
    !---------------------------------------------
    !> \ingroup generic_module
    !> \details
    !> \p rocsparse_sddmm_buffer_size returns the size of the required buffer to execute the SDDMM
    !> operation from a given configuration.
    !> This routine is used in conjunction with \ref rocsparse_sddmm_preprocess() and \ref
    !> rocsparse_sddmm().
    !>
    !> \note
    !> This routine does not support execution in a hipGraph context.
    !>
    !> @param[in]
    !> handle       handle to the rocSPARSE library context queue.
    !> @param[in]
    !> opA          dense matrix \f$A\f$ operation type.
    !> @param[in]
    !> opB          dense matrix \f$B\f$ operation type.
    !> @param[in]
    !> alpha        scalar \f$\alpha\f$.
    !> @param[in]
    !> mat_A        dense matrix \f$A\f$ descriptor.
    !> @param[in]
    !> mat_B        dense matrix \f$B\f$ descriptor.
    !> @param[in]
    !> beta         scalar \f$\beta\f$.
    !> @param[inout]
    !> mat_C        sparse matrix \f$C\f$ descriptor.
    !> @param[in]
    !> compute_type floating point precision for the SDDMM computation.
    !> @param[in]
    !> alg specification of the algorithm to use.
    !> @param[out]
    !> buffer_size  number of bytes of the temporary storage buffer.
    !>
    !> \retval rocsparse_status_success the operation completed successfully.
    !> \retval rocsparse_status_invalid_value the value of \p opA or \p opB is incorrect.
    !> \retval rocsparse_status_invalid_handle the library context was not initialized.
    !> \retval rocsparse_status_invalid_pointer \p alpha and \p beta are invalid,
    !> or the \p mat_A, \p mat_B, \p mat_C, or \p buffer_size pointer is invalid.
    !> \retval rocsparse_status_not_implemented
    !> \p opA == \ref rocsparse_operation_conjugate_transpose or
    !> \p opB == \ref rocsparse_operation_conjugate_transpose.
    function rocsparse_sddmm_buffer_size(handle, opA, opB, alpha, mat_A, mat_B, beta, mat_C, &
                                         compute_type, alg, buffer_size) &
       result(sddmm_buffer_size) &
       bind(C, name="rocsparse_sddmm_buffer_size")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: opA
       integer(c_int), value :: opB
       type(c_ptr), value :: alpha
       type(c_ptr), value :: mat_A
       type(c_ptr), value :: mat_B
       type(c_ptr), value :: beta
       type(c_ptr), value :: mat_C
       integer(c_int), value :: compute_type
       integer(c_int), value :: alg
       type(c_ptr), value :: buffer_size
       integer(c_int) :: sddmm_buffer_size
    end function rocsparse_sddmm_buffer_size

    !---------------------------------------------
    ! rocsparse_sddmm_preprocess
    !---------------------------------------------
    !> \ingroup generic_module
    !> \details
    !> \p rocsparse_sddmm_preprocess executes a part of the algorithm that can be calculated once in
    !> the context of multiple
    !> calls of the \ref rocsparse_sddmm with the same sparsity pattern.
    !>
    !> \note
    !> This routine does not support execution in a hipGraph context.
    !>
    !> @param[in]
    !> handle       handle to the rocSPARSE library context queue.
    !> @param[in]
