       bind(C, name="rocsparse_sgtsv")
       import :: c_ptr, c_int, c_float
       type(c_ptr), value :: handle
       integer(c_int), value :: m
       integer(c_int), value :: n
       real(c_float) :: dl(*)
       real(c_float) :: d(*)
       real(c_float) :: du(*)
       real(c_float) :: B(*)
       integer(c_int), value :: ldb
       type(c_ptr), value :: temp_buffer
       integer(c_int) :: sgtsv
    end function rocsparse_sgtsv

